oracle.patch:
diff --git a/src/merge-config.mjs b/src/merge-config.mjs
--- a/src/merge-config.mjs
+++ b/src/merge-config.mjs
@@ -1,5 +1,15 @@
 export function mergeConfig(defaults, overrides) {
-  return Object.fromEntries(
-    Object.entries(defaults).map(([key, value]) => [key, overrides[key] || value]),
-  )
+  const result = {}
+  for (const key of new Set([...Object.keys(defaults), ...Object.keys(overrides)])) {
+    const fallback = defaults[key]
+    const supplied = Object.hasOwn(overrides, key) ? overrides[key] : fallback
+    if (isRecord(fallback) && isRecord(supplied)) {
+      result[key] = mergeConfig(fallback, supplied)
+    } else {
+      result[key] = supplied
+    }
+  }
+  return result
 }
+
+function isRecord(value) {
+  return value !== null && typeof value === 'object' && !Array.isArray(value)
+}

mutants.patch:
diff --git a/src/merge-config.mjs b/src/merge-config.mjs
--- a/src/merge-config.mjs
+++ b/src/merge-config.mjs
@@ -1,5 +1,7 @@
 export function mergeConfig(defaults, overrides) {
   return Object.fromEntries(
-    Object.entries(defaults).map(([key, value]) => [key, overrides[key] || value]),
+    Object.entries(defaults).map(([key, value]) => [
+      key, Object.hasOwn(overrides, key) ? overrides[key] : value,
+    ]),
   )
 }

diff --git a/src/merge-config.mjs b/src/merge-config.mjs
--- a/src/merge-config.mjs
+++ b/src/merge-config.mjs
@@ -1,5 +1,5 @@
 export function mergeConfig(defaults, overrides) {
   return Object.fromEntries(
-    Object.entries(defaults).map(([key, value]) => [key, overrides[key] || value]),
+    Object.entries(defaults).map(([key, value]) => [key, overrides[key] === false ? false : overrides[key] || value]),
   )
 }
